using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
public static class FixTelevisionContactWindowCycle02{
 public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling)throw new Exception("Idle required");for(int i=0;i<SceneManager.sceneCount;i++)if(SceneManager.GetSceneAt(i).isDirty)throw new Exception("Dirty scene");var setup=EditorSceneManager.GetSceneManagerSetup();try{var scene=EditorSceneManager.OpenScene("Assets/ShooterSurvival/Scenes/Tools/ShoeTower.unity");var h=UnityEngine.Object.FindFirstObjectByType<Chapter45Director>().hazards.Single(x=>x.name=="4F falling television");if(h.warningDistance!=22||h.lingerSeconds!=0)throw new Exception("Unexpected baseline");h.lingerSeconds=1.2f;EditorUtility.SetDirty(h);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);EditorSceneManager.OpenScene(scene.path);h=UnityEngine.Object.FindFirstObjectByType<Chapter45Director>().hazards.Single(x=>x.name=="4F falling television");return new{h.name,h.warningDistance,h.lingerSeconds,h.damageFraction,h.safeLane,reopened=true,reason="Keep visible landed debris and trigger alive for actual physics steps; previous hazard vanished in its landing Update."};}finally{EditorSceneManager.RestoreSceneManagerSetup(setup);}}
}
